132	     * @param e The {@link DuplicateTelephoneException} to be handled
133	     * @param request {@link HttpServletRequest} object referring to the current request.
134	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status
135	     */
136	    @ExceptionHandler(DuplicateTelephoneException.class)
137	    @ResponseBody
138	    public ResponseEntity<ProblemDetail> handleDuplicateTelephoneException(DuplicateTelephoneException e, HttpServletRequest request) {
139	        logger.warn("Duplicate telephone at {} {}: {}",
140	            request.getMethod(),
141	            request.getRequestURI(),
142	            e.getMessage());
143	        HttpStatus status = HttpStatus.CONFLICT;
144	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_TELEPHONE);
145	        return ResponseEntity.status(status).body(detail);
146	    }
147	
148	    /**
149	     * Handles {@link InvalidTelephoneException}, raised when a supplied telephone value cannot be
150	     * normalized to a valid E.164 number, returning a 400 Bad Request status.
151	     *
152	     * @param e The {@link InvalidTelephoneException} to be handled
153	     * @param request {@link HttpServletRequest} object referring to the current request.
154	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status
155	     */
156	    @ExceptionHandler(InvalidTelephoneException.class)
157	    @ResponseBody
158	    public ResponseEntity<ProblemDetail> handleInvalidTelephoneException(InvalidTelephoneException e, HttpServletRequest request) {
159	        logger.warn("Invalid telephone at {} {}: {}",
160	            request.getMethod(),
161	            request.getRequestURI(),
162	            e.getMessage());
163	        HttpStatus status = HttpStatus.BAD_REQUEST;
164	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_TELEPHONE);
165	        return ResponseEntity.status(status).body(detail);
