182	        if (bindingResult.hasErrors()) {
183	            errors.addAllErrors(bindingResult);
184	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
185	                .map(fieldError -> {
186	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
