188	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
189	                        fieldError.getField(),
190	                        defaultMessage,
191	                        rejectedValue);
192	                    return new ValidationMessageDto(message)
193	                        .putAdditionalProperty("field", fieldError.getField())
194	                        .putAdditionalProperty("rejectedValue", rejectedValue)
195	                        .putAdditionalProperty("defaultMessage", defaultMessage);
196	                })
197	                .toList();
198	            logger.debug("Validation error at {} {}: {}",
