80	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
81	    @Override
82	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
83	        Collection<Owner> owners;
84	        if (lastName != null) {
85	            owners = this.clinicService.findOwnerByLastName(lastName);
86	        } else {
87	            owners = this.clinicService.findAllOwners();
88	        }
89	        if (owners.isEmpty()) {
90	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
91	        }
92	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
93	    }
94	
95	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
96	    @Override
97	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
98	        Owner owner = this.clinicService.findOwnerById(ownerId);
99	        if (owner == null) {
100	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
101	        }
102	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
108	        HttpHeaders headers = new HttpHeaders();
109	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
110	        // Normalize the telephone on create so it is stored and returned in canonical E.164 form.
111	        // A value that cannot form a valid E.164 number is rejected with 400.
112	        String normalizedTelephone = telephoneNormalizer.normalize(owner.getTelephone());
113	        owner.setTelephone(normalizedTelephone);
114	        // Store the (already syntactically validated) email lower-cased so it is persisted and
115	        // returned in canonical form. A missing email is left untouched.
116	        owner.setEmail(normalizeEmail(owner.getEmail()));
117	        // Default the registration date to the server's current date when the client did not
118	        // supply one, so it is persisted and returned in ISO 'YYYY-MM-DD' form.
119	        if (owner.getRegistrationDate() == null) {
120	            owner.setRegistrationDate(java.time.LocalDate.now());
121	        }
122	        // Reject creating an owner whose normalized telephone is already used by another owner.
123	        if (isTelephoneInUse(normalizedTelephone)) {
124	            throw new DuplicateTelephoneException(
125	                "An owner with telephone " + normalizedTelephone + " already exists");
126	        }
127	        // Assign the customer code '<LAST3>-<NNNN>' from the last name and a global sequence
128	        // equal to one more than the current number of owners, fixed at creation time.
129	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
130	        this.clinicService.saveOwner(owner);
131	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
132	        headers.setLocation(UriComponentsBuilder.newInstance()
133	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
134	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
135	    }
136	
137	    /**
138	     * Lower-cases the supplied email address so it is stored and returned in canonical form.
139	     * Bean validation on the request DTO has already guaranteed that any non-null value is a
140	     * syntactically valid address (rejecting anything else with 400).
141	     *
142	     * @param email the email value (may be {@code null})
143	     * @return the lower-cased email, or {@code null} if the input was {@code null}
144	     */
145	    private String normalizeEmail(String email) {
146	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
147	    }
148	
149	    /**
150	     * Builds the customer code '<LAST3>-<NNNN>' for a newly created owner, where LAST3 is the
151	     * upper-cased first three letters of the last name and NNNN is a global 4-digit zero-padded
152	     * sequence equal to one more than the current number of owners (e.g. 'SMI-0007').
153	     *
154	     * @param lastName the owner's last name
155	     * @return the formatted customer code
156	     */
157	    private String nextCustomerCode(String lastName) {
158	        String prefix = lastName.substring(0, Math.min(3, lastName.length()))
159	            .toUpperCase(java.util.Locale.ROOT);
160	        int sequence = this.clinicService.findAllOwners().size() + 1;
161	        return String.format("%s-%04d", prefix, sequence);
162	    }
163	
164	    /**
165	     * Determines whether the given normalized telephone is already used by an existing owner.
166	     * Stored telephones are normalized to E.164 before comparison so values that differ only in
167	     * formatting (spaces, dashes, brackets) or in national vs. international notation are treated
168	     * as the same number.
169	     *
170	     * @param normalizedTelephone the normalized (E.164) telephone to look for
171	     * @return {@code true} if another owner already uses this telephone
172	     */
173	    private boolean isTelephoneInUse(String normalizedTelephone) {
174	        if (normalizedTelephone == null) {
175	            return false;
176	        }
177	        return this.clinicService.findAllOwners().stream()
178	            .map(Owner::getTelephone)
179	            .map(telephoneNormalizer::normalize)
180	            .anyMatch(normalizedTelephone::equals);
181	    }
