187	        if (currentOwner == null) {
188	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
189	        }
190	        currentOwner.setAddress(ownerFieldsDto.getAddress());
191	        currentOwner.setCity(ownerFieldsDto.getCity());
192	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
193	        currentOwner.setLastName(ownerFieldsDto.getLastName());
194	        // Normalize the telephone to canonical E.164 form so it is stored and returned
195	        // consistently with create; an unformattable value is rejected with 400.
196	        currentOwner.setTelephone(telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
197	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
198	        this.clinicService.saveOwner(currentOwner);
199	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
200	    }
