265	
266	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
267	    @Override
268	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
269	        Owner owner = this.clinicService.findOwnerById(ownerId);
270	        if (owner != null) {
271	            Pet pet = owner.getPet(petId);
272	            if (pet != null) {
273	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
274	            }
275	        }
276	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
277	    }
278	}
